-- ==========================================================
-- update_movies_400.sql
-- Replaces the movie catalog with 400 movies: 40 for every genre
-- (20 Hollywood + 20 Bollywood per genre, across 10 genres).
-- All titles and descriptions are original / fictional -- not
-- copied from any real film -- so there are no copyright issues.
-- Run this on your existing movie_booking database.
--
-- After importing, go to Admin -> Bulk Setup (seed_data.php) and
-- click "Run" -- it will automatically:
--   - create a screen + seat map for every theater that doesn't
--     have one yet ("screens" option), and
--   - schedule shows for all 400 movies.
-- (Industry is already set correctly below, so that step will
-- just skip it.)
-- ==========================================================

SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM reviews;
DELETE FROM booking_seats;
DELETE FROM bookings;
DELETE FROM shows;
DELETE FROM movies;
ALTER TABLE movies AUTO_INCREMENT = 1;
SET FOREIGN_KEY_CHECKS = 1;

